// ui-general · кейс ui-05 (.qa/tests/ui-general/) — דוח לרואה חשבון (только чтение + скачивание)
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const iso = (d: Date) => d.toISOString().slice(0, 10);
const today = iso(new Date());
const from = iso(new Date(Date.now() - 60 * 864e5));

async function openReport(page: Page) {
  await page.goto('/dashboard');
  const card = page.getByRole('heading', { name: 'דוח לרואה חשבון' });
  await expect(card).toBeVisible({ timeout: 20_000 });
  await page.getByRole('textbox', { name: 'מתאריך' }).fill(from);
  await page.getByRole('textbox', { name: 'עד תאריך' }).fill(today);
  await page.getByRole('button', { name: 'הפקת הדוח' }).click();
  await expect(page).toHaveURL(new RegExp(`/reports/accounting\\?from=${from}&to=${today}`));
  await expect(page.getByRole('heading', { level: 1, name: 'דוח לרואה חשבון' })).toBeVisible();
}

test.describe('ui-general — דוח לרואה חשבון', () => {
  test('הפקה מהדשבורד לפי טווח: עמודות, סיכומים, רק מאושרות, הערה על מספר תשלומים #6a7b3fa8 @desktop @prod-safe', async ({ page }) => {
    await openReport(page);
    for (const t of ['סה״כ לפני מע״מ', 'סה״כ מע״מ', 'סה״כ כולל מע״מ', 'שולם בפועל']) await expect(page.getByText(t, { exact: true }).first()).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(/יתרה לגבייה ₪/)).toBeVisible();
    await expect(page.getByText(/^\d+ מסמכים$/)).toBeVisible();
    const head = await page.locator('table').first().locator('th').allInnerTexts();
    expect(head.map((h) => h.trim())).toEqual(['תאריך', 'מסמך', 'לקוח', 'אמצעי תשלום', 'תשלום', 'זיכוי', 'לפני מע״מ', 'מע״מ', 'סה״כ כולל מע״מ']);
    await expect(page.getByText('הזמנות ששולמו במזומן')).toBeVisible();
    // «לכלול בדוח» / «להחריג מהדוח» — <option> בתוך <select> (תמיד "hidden"), בודקים את אפשרויות ה-select
    const cashSelect = page.locator('select').filter({ has: page.locator('option', { hasText: 'לכלול בדוח' }) });
    await expect(cashSelect.locator('option', { hasText: 'לכלול בדוח' })).toHaveCount(1);
    await expect(cashSelect.locator('option', { hasText: 'להחריג מהדוח' })).toHaveCount(1);
    await expect(page.getByText(/^מספר תשלומים אינו נרשם במערכת/)).toBeVisible();
    // Только утверждённые: в таблице нет статуса «נדחתה»/«ממתינה לאישור».
    await expect(page.locator('table').first().getByText(/נדחתה|ממתינה לאישור/)).toHaveCount(0);
  });

  test('הורדת PDF וייצוא לאקסל מורידים קבצים #6a7b3fa8 @desktop @prod-safe', async ({ page }) => {
    await openReport(page);
    await expect(page.getByText(/^\d+ מסמכים$/)).toBeVisible({ timeout: 20_000 });
    // «הורדת PDF» לפי תכנון פותח הדפסת דפדפן (window.print), לא מוריד קובץ
    await page.evaluate(() => { (window as any).__printed = 0; window.print = () => { (window as any).__printed++; }; });
    await page.getByRole('button', { name: 'הורדת PDF' }).click();
    await expect.poll(() => page.evaluate(() => (window as any).__printed)).toBe(1);
    const [xlsx] = await Promise.all([page.waitForEvent('download', { timeout: 30_000 }), page.getByRole('button', { name: 'ייצוא לאקסל' }).click()]);
    expect(xlsx.suggestedFilename()).toMatch(/\.xlsx$/i);
  });

  test('טווח מעל 366 ימים ותאריך סיום לפני התחלה — הודעה ברורה #6a7b3fa8 @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/reports/accounting?from=2025-01-01&to=${today}`);
    await expect(page.getByText('ניתן להפיק דוח לטווח של עד 366 ימים')).toBeVisible({ timeout: 20_000 });
    await page.goto(`/reports/accounting?from=${today}&to=2026-01-01`);
    await expect(page.getByText('תאריך הסיום מוקדם מתאריך ההתחלה')).toBeVisible({ timeout: 20_000 });
  });
});
